def separate_paren_groups(input_str):
    '''Separates input string into a list of balanced parentheses groups.
    Ignores whitespace and collects only complete top-level balanced groups.'''
    groups = []
    buffer = ''
    depth = 0
    invalid_extra_close = False
    for char in input_str:
        if char.isspace():
            continue
        if char == '(':
            if depth == 0:
                buffer = ''
            depth += 1
            buffer += char
        elif char == ')':
            if depth == 0:
                invalid_extra_close = True
            else:
                depth -= 1
                buffer += char
                if depth == 0:
                    groups.append(buffer)
                    buffer = ''
        else:
            if depth > 0:
                buffer += char
    if invalid_extra_close:
        return []
    return groups

