def count_balanced_paren_groups(input_str):
    """Counts the number of balanced parentheses groups in the input string.
    Returns the count of groups, or 0 if the input contains unmatched parentheses."""
    depth = 0
    count = 0
    for char in input_str:
        if char == '(':
            if depth == 0:
                count += 1
            depth += 1
        elif char == ')':
            if depth == 0:
                return 0
            depth -= 1
    if depth != 0:
        return 0
    return count

